css:
:root[data-theme="dark"] {
  --ds-bg-primary: var(--sax-surface);
  --sax-surface: hsl(245 32% 13%);
  --ds-bg-secondary: var(--sax-canvas);
  --sax-canvas: hsl(245 48% 10%);
  --ds-bg-dock: var(--sax-glass);
  --sax-glass: hsl(245 42% 16% / 0.7);
  --ds-bg-elevated-opaque: var(--sax-raised);
  --sax-raised: hsl(245 38% 18%);
  --ds-text-primary: var(--sax-ink);
  --sax-ink: hsl(245 32% 96%);
  --ds-text-secondary: var(--sax-secondary);
  --sax-secondary: hsl(245 24% 82%);
  --ds-border-default: hsl(220 0% 0% / 0);
  --ds-accent: var(--sax-action);
  --sax-action: var(--sax-primary-fill);
  --sax-primary-fill: hsl(var(--sax-primary-h) var(--sax-fill-s) var(--sax-fill-l));
  --sax-primary-h: 252;
  --sax-fill-s: 92%;
  --sax-fill-l: 74%;
  --ds-bg-active: hsl(var(--sax-primary-h) 90% 60% / .16);
  --ds-error: var(--sax-error);
  --sax-error: hsl(var(--sax-error-h) var(--sax-base-s) var(--sax-base-l));
  --sax-error-h: 4;
  --sax-base-s: 88%;
  --sax-base-l: 76%;
  --ds-success: var(--sax-success);
  --sax-success: hsl(var(--sax-success-h) var(--sax-base-s) var(--sax-base-l));
  --sax-success-h: 150;
  --ds-placeholder-ink: var(--sax-muted);
  --sax-muted: hsl(245 18% 70%);
}
